const std::string current_name = "zh_CN.UTF-8";
static constexpr const char* fixed_name = "C";

// 1. Construction using std::string reference
// Compiler must handle potential runtime string memory access.
std::locale loc_string(current_name);

// 2. Construction using explicit C-style string
// Mandated by standard to yield identical result to (1)
std::locale loc_cstr(current_name.c_str());

// 3. Maximized Optimization Path
// Compiler can often read and inline the name string directly.
std::locale loc_optimized(fixed_name);

// Changing the process locale
std::locale::global(loc_string);
